import java.io.*;import java.util.*;import com.android.tools.smali.dexlib2.*;import com.android.tools.smali.dexlib2.iface.*;import com.android.tools.smali.dexlib2.iface.instruction.*;
public class PenContracts {public static void main(String[] a)throws Exception{var con=DexFileFactory.loadDexContainer(new File(a[0]),Opcodes.forApi(36));for(var en:con.getDexEntryNames())for(var c:con.getEntry(en).getDexFile().getClasses()){String t=c.getType();boolean match=t.contains("btadsorb/ble/")||t.equals("Lcom/oplus/ipemanager/btadsorb/CoreService;")||t.equals("Lcom/oplus/ipemanager/btadsorb/util/p;")||t.equals("LF2/y;")||t.equals("Lcom/oplus/ipemanager/btadsorb/util/v;")||t.equals("Lb2/b;")||t.equals("Lv1/b;")||t.contains("PencilUtil")||t.contains("pencil/Pencil")||t.equals("Lcom/oplus/wirelesssettings/bluetooth/model/j;")||t.equals("Lcom/oplus/wirelesssettings/utils/q;")||t.equals("Lcom/oplus/wirelesssettings/utils/d;")||t.equals("Lcom/oplus/wirelesssettings/bluetooth/BluetoothTileDevicePreference;");if(!match)continue;System.out.println("CLASS "+en+" "+t+" EXTENDS "+c.getSuperclass());for(var f:c.getFields())System.out.println("FIELD "+f);for(var m:c.getMethods()){System.out.println("METHOD "+m);if(m.getImplementation()!=null)for(var i:m.getImplementation().getInstructions()){if(i instanceof ReferenceInstruction ri)System.out.println("  "+i.getOpcode()+" "+ri.getReference());}}}}}
